go run - <<'GOEOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type declKey struct {
	pkgPath string
	name    string
	file    string
}

func main() {
	root := "/bench/repo"
	internal := filepath.Join(root, "internal")

	fset := token.NewFileSet()
	decls := map[declKey]struct{}{}
	pkgImport := map[string]string{} // dir -> import path suffix

	filepath.Walk(internal, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		rel, _ := filepath.Rel(root, filepath.Dir(path))
		rel = filepath.ToSlash(rel)
		pkgImport[rel] = "github.com/usememos/memos/" + rel

		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil
		}
		for _, d := range f.Decls {
			fn, ok := d.(*ast.FuncDecl)
			if !ok || fn.Name == nil || !fn.Name.IsExported() {
				continue
			}
			relFile, _ := filepath.Rel(root, path)
			decls[declKey{pkgPath: rel, name: fn.Name.Name, file: filepath.ToSlash(relFile)}] = struct{}{}
		}
		return nil
	})

	// collect all packages for call scanning
	type pkgInfo struct {
		dir    string
		importPath string
		name   string
	}
	var pkgs []pkgInfo
	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		if strings.Contains(path, string(filepath.Separator)+"proto"+string(filepath.Separator)+"gen"+string(filepath.Separator)) {
			return nil
		}
		if strings.Contains(path, string(filepath.Separator)+"web"+string(filepath.Separator)) {
			return nil
		}
		dir := filepath.Dir(path)
		if _, done := pkgImport[filepath.ToSlash(filepath.Rel(root, dir))]; done {
			// will parse below
		}
		return nil
	})

	// parse all non-test non-gen go files once
	type fileAST struct {
		pkgDir string
		f      *ast.File
	}
	var files []fileAST
	filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		if strings.Contains(path, "/proto/gen/") || strings.Contains(path, "/web/") {
			return nil
		}
		dir, _ := filepath.Rel(root, filepath.Dir(path))
		dir = filepath.ToSlash(dir)
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil
		}
		files = append(files, fileAST{pkgDir: dir, f: f})
		return nil
	})

	// build import alias map per file: local name -> import path
	importPathFor := func(f *ast.File, alias string) string {
		for _, imp := range f.Imports {
			p := strings.Trim(imp.Path.Value, `"`)
			local := alias
			if imp.Name != nil {
				local = imp.Name.Name
			} else {
				local = filepath.Base(p)
			}
			if local == alias {
				return p
			}
		}
		return ""
	}

	fanin := map[declKey]int{}

	for d := range decls {
		fanin[d] = 0
	}

	for _, fa := range files {
		imports := map[string]string{}
		for _, imp := range fa.f.Imports {
			p := strings.Trim(imp.Path.Value, `"`)
			local := filepath.Base(p)
			if imp.Name != nil {
				local = imp.Name.Name
			}
			imports[local] = p
		}

		ast.Inspect(fa.f, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			switch fun := call.Fun.(type) {
			case *ast.SelectorExpr:
				// pkg.Func or recv.Method
				if id, ok := fun.X.(*ast.Ident); ok {
					imp := imports[id.Name]
					if imp != "" {
						// package qualified
						suffix := strings.TrimPrefix(imp, "github.com/usememos/memos/")
						key := declKey{pkgPath: suffix, name: fun.Sel.Name}
						if _, exists := decls[key]; exists {
							fanin[key]++
						}
					} else if fa.pkgDir == decls[declKey{pkgPath: fa.pkgDir, name: fun.Sel.Name}].pkgPath {
						// same package method call - harder; skip methods for now focus funcs
					}
				} else {
					// method call on value - check if method declared in internal
					key := declKey{name: fun.Sel.Name}
					for d := range decls {
						if d.name == fun.Sel.Name {
							// could be method on type in package - count if selector type in same pkg?
							// approximate: count all internal methods by name (may overcount)
						}
					}
					_ = key
				}
			case *ast.Ident:
				// bare Func() in same package
				key := declKey{pkgPath: fa.pkgDir, name: fun.Name}
				if _, exists := decls[key]; exists {
					fanin[key]++
				}
			}
			return true
		})
	}

	type result struct {
		count int
		name  string
		file  string
		pkg   string
	}
	var results []result
	for d, c := range fanin {
		results = append(results, result{count: c, name: d.name, file: d.file, pkg: d.pkgPath})
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].count != results[j].count {
			return results[i].count > results[j].count
		}
		return results[i].name < results[j].name
	})
	for i, r := range results {
		if i >= 30 {
			break
		}
		fmt.Printf("%d\t%s\t%s\t%s\n", r.count, r.name, r.file, r.pkg)
	}
}
GOEOF

perl << 'PERL'
use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = '/bench/repo';
my $internal = "$root/internal";

# Find declarations in internal non-test go files
my %decls;  # key "pkg\tname" => file
find(sub {
    return unless -f && /\.go$/ && !/_test\.go$/;
    my $file = $File::Find::name;
    return unless index($file, $internal) == 0;
    open my $fh, '<', $file or return;
    my $rel = substr($file, length($root)+1);
    my $pkg = dirname($rel);
    $pkg =~ s{\\}{/}g;
    while (<$fh>) {
        if (/^func (?:\([^)]*\)\s+)?([A-Z][A-Za-z0-9_]*)/) {
            my $sym = $1;
            $decls{"$pkg\t$sym"} = $rel;
        }
    }
    close $fh;
}, $internal);

# Collect caller files
my @caller_files;
find(sub {
    return unless -f && /\.go$/ && !/_test\.go$/;
    my $file = $File::Find::name;
    return if index($file, '/proto/gen/') >= 0;
    return if index($file, '/web/') >= 0;
    push @caller_files, $file;
}, $root);

my %fanin;
for my $k (keys %decls) { $fanin{$k} = 0; }

for my $file (@caller_files) {
    open my $fh, '<', $file or next;
    my $rel = substr($file, length($root)+1);
    my $fpkg = dirname($rel);
    $fpkg =~ s{\\}{/}g;
    my $lineno = 0;
    while (<$fh>) {
        $lineno++;
        for my $k (keys %decls) {
            my ($pkg, $sym) = split /\t/, $k;
            my $declfile = $decls{$k};
            my $pkgshort = (split /\//, $pkg)[-1];
            # skip declaration line in same file
            if ($rel eq $declfile && /^func (?:\([^)]*\)\s+)?\Q$sym\E\s*\(/) {
                next;
            }
            my $count = 0;
            $count += () = /\Q$pkgshort\E\.\Q$sym\E\s*\(/g;
            if ($fpkg eq $pkg) {
                $count += () = /(?:^|[^.\w])\Q$sym\E\s*\(/g;
            }
            $fanin{$k} += $count if $count;
        }
    }
    close $fh;
}

my @sorted = sort { $fanin{$b} <=> $fanin{$a} || $a cmp $b } keys %fanin;
for my $i (0..29) {
    last unless defined $sorted[$i];
    my $k = $sorted[$i];
    my ($pkg, $sym) = split /\t/, $k;
    print "$fanin{$k}\t$sym\t$decls{$k}\t$pkg\n";
}
PERL

