    my $c=0;
    for my $line (@lines) {
      next if $rel eq $df && $line =~ /^func (?:\([^)]*\)\s+)?\Q$sym\E\s*\(/;
      if ($recv eq "") {
        $c += () = $line =~ /\Q$ps\E\.\Q$sym\E\s*\(/g;
        $c += () = $line =~ /(?:^|[^.\w])\Q$sym\E\s*\(/g if $fpkg eq $pkg;
      } else {
        # method: count .sym( only within declaring package
        $c += () = $line =~ /\.\Q$sym\E\s*\(/g if $fpkg eq $pkg;
      }
    }
    $fanin{$k} += $c;
  }
}

my @sorted = sort { $fanin{$b} <=> $fanin{$a} || $a cmp $b } keys %fanin;
for (0..19) {
  my $k=$sorted[$_]; my ($pkg,$sym,$recv)=split /\t/,$k;
  my $symdisp = $recv ? "($recv).$sym" : $sym;
  print "$fanin{$k}\t$symdisp\t$decls{$k}\n";
}
